702	    __aicore__ inline void CopyInX(int32_t rowIdx, int32_t colBase, int32_t validN)
703	    {
704	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
705	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase], static_cast<uint32_t>(validN));
706	        xInQueue_.EnQue(xInLocal_);
707	    }
708	
709	    __aicore__ inline void CopyInGamma(int32_t colBase, int32_t validN)
710	    {
711	        gammaInLocal_ = gammaInQueue_.AllocTensor<dataType>();
712	        LoadGmToUb(gammaInLocal_, gammaGM_[colBase], static_cast<uint32_t>(validN));
713	        gammaInQueue_.EnQue(gammaInLocal_);
714	    }
715	
716	    __aicore__ inline void CopyOutY(int32_t rowIdx, int32_t colBase, int32_t validN)
717	    {
718	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
719	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N + colBase], yOutLocal_, static_cast<uint32_t>(validN));
720	        yOutQueue_.FreeTensor(yOutLocal_);
721	    }
722	
723	    __aicore__ inline void CopyOutInvRms(int32_t rowIdx)
724	    {
725	        invRmsOutLocal_ = invRmsOutQueue_.DeQue<dataType>();
726	        StoreUbToGm(invRmsGM_[rowIdx], invRmsOutLocal_, 1);
727	        invRmsOutQueue_.FreeTensor(invRmsOutLocal_);
728	    }
