730	    __aicore__ inline float ComputeInvRms(int32_t rowIdx)
731	    {
732	        reduceLocal_ = reduceBuf_.Get<float>();
733	        sumLocal_ = sumBuf_.Get<float>();
734	        tempLocal_ = tempBuf_.Get<float>();
735	        invRmsOutLocal_ = invRmsOutQueue_.AllocTensor<dataType>();
736	        PrepareInvRmsTensorHelper<dataType>(invRmsLocal_, invRmsOutLocal_, invRmsBuf_);
737	        float sumSq = 0.0f;
738	
739	        for (int by = 0; by < NumTiles(); ++by) {
740	            const int colBase = by * kBlockN;
741	            const int validN = GetValidN(colBase);
742	
743	            CopyInX(rowIdx, colBase, validN);
744	
745	            xInLocal_ = xInQueue_.DeQue<dataType>();
746	            PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
747	            AscendC::Mul(tempLocal_, xLocal_, xLocal_, validN);
748	            AscendC::ReduceSum<float>(sumLocal_, tempLocal_, reduceLocal_, validN);
749	            sumSq += sumLocal_.GetValue(0);
750	            xInQueue_.FreeTensor(xInLocal_);
751	        }
752	
753	        AscendC::Duplicate(sumLocal_, sumSq * invN + eps, 1);
754	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
755	        AscendC::PipeBarrier<PIPE_ALL>();
756	        float invRms = invRmsLocal_.GetValue(0);
757	        AscendC::PipeBarrier<PIPE_ALL>();
758	        FinalizeOutputTensorHelper<dataType>(invRmsOutLocal_, invRmsLocal_, 1);
759	
760	        invRmsOutQueue_.EnQue(invRmsOutLocal_);
761	        return invRms;
762	    }
763	
764	    __aicore__ inline void ComputeTile(float invRms, int32_t validN)
765	    {
766	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
767	        xInLocal_ = xInQueue_.DeQue<dataType>();
768	        gammaInLocal_ = gammaInQueue_.DeQue<dataType>();
769	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
770	        PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, validN);
771	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
772	        AscendC::Muls(yLocal_, xLocal_, invRms, validN);
773	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, validN);
774	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, validN);
775	        xInQueue_.FreeTensor(xInLocal_);
776	        gammaInQueue_.FreeTensor(gammaInLocal_);
777	        yOutQueue_.EnQue(yOutLocal_);
778	    }
779	
780	    __aicore__ inline void ProcessRow(int rowIdx)
781	    {
782	        float invRms = ComputeInvRms(rowIdx);
783	        CopyOutInvRms(rowIdx);
784	
785	        for (int by = 0; by < NumTiles(); ++by) {
786	            const int colBase = by * kBlockN;
787	            const int validN = GetValidN(colBase);
788	
789	            CopyInX(rowIdx, colBase, validN);
790	            CopyInGamma(colBase, validN);
791	            ComputeTile(invRms, validN);
792	            CopyOutY(rowIdx, colBase, validN);
793	        }
794	    }
