// Hyena FFT kernel: zero-pad + rFFT + normalize
// Cooley-Tukey radix-2 DIT FFT with precomputed twiddle factors

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// =========================================================================
// Inline helpers
// =========================================================================

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Bit-reverse helper: reverse log2(N) bits of an integer
// =========================================================================

__aicore__ inline int32_t BitReverse(int32_t idx, int32_t numBits)
{
    int32_t result = 0;
    for (int32_t i = 0; i < numBits; ++i) {
        result = (result << 1) | (idx & 1);
        idx >>= 1;
    }
    return result;
}

// =========================================================================
// FFT Kernel
// =========================================================================

template <typename T>
class KernelHyenaFft {
public:
    __aicore__ inline void Init(
        GM_ADDR x,
        GM_ADDR y_real,
        GM_ADDR y_imag,
        GM_ADDR twiddle,
        int32_t B,
        int32_t C,
        int32_t L,
        int32_t usedCoreNum,
        int32_t tasksPerCore,
        int64_t dtypeFlag)
    {
        this->B = B;
        this->C = C;
        this->L = L;
        this->N = 2 * L;
        this->outSize = L + 1;
        this->totalTasks = B * C;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->dtypeFlag_ = dtypeFlag;

        // Compute log2(N) for FFT stages and bit-reversal
        int32_t temp = N;
        numStages_ = 0;
        while (temp > 1) {
            temp >>= 1;
            numStages_++;
        }

        // Set up GM tensors
        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), static_cast<uint64_t>(B) * C * L);
        yRealGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(y_real),
                                  static_cast<uint64_t>(B) * C * outSize);
        yImagGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(y_imag),
                                  static_cast<uint64_t>(B) * C * outSize);
        twiddleGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(twiddle),
                                    static_cast<uint32_t>(N));

        if (ASCEND_IS_AIV) {
            InitAivBuffers();
        }
    }

    __aicore__ inline void InitAivBuffers()
    {
        // UB allocation plan:
        //   dataBuf_:     2*N float32  (interleaved complex data)
        //   twiddleBuf_:  N float32    (interleaved twiddle factors)
        //   inputBuf_:    L * sizeof(T) (raw input)
        //   outBuf_:      outSize float32 (temp for one output row)
        uint32_t dataBytes = 2U * static_cast<uint32_t>(N) * sizeof(float);
        uint32_t twiddleBytes = static_cast<uint32_t>(N) * sizeof(float);
        uint32_t inputBytes = static_cast<uint32_t>(L) * sizeof(T);
        uint32_t outBytes = static_cast<uint32_t>(outSize) * sizeof(float);

        pipe_.InitBuffer(dataBuf_, dataBytes);
        pipe_.InitBuffer(twiddleBuf_, twiddleBytes);
        pipe_.InitBuffer(inBuf_, inputBytes);
        pipe_.InitBuffer(outRealBuf_, outBytes);
        pipe_.InitBuffer(outImagBuf_, outBytes);
        if constexpr (!std::is_same_v<T, float>) {
            pipe_.InitBuffer(castBuf_, static_cast<uint32_t>(L) * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if (ASCEND_IS_AIV) {
            int32_t coreIdx = static_cast<int32_t>(AscendC::GetBlockIdx());

            for (int32_t localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                int32_t taskId = coreIdx * tasksPerCore + localIdx;
                if (taskId >= totalTasks) {
                    continue;
                }

                int32_t bi = taskId / C;
                int32_t ci = taskId % C;

                CopyIn(bi, ci);
                Compute();
                CopyOut(bi, ci);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t bi, int32_t ci)
    {
        // --- Load twiddle factors ---
        {
            AscendC::LocalTensor<float> twLocal = twiddleBuf_.Get<float>();
            AscendC::DataCopyExtParams copyParams{
                1, static_cast<uint16_t>(static_cast<uint32_t>(N) * sizeof(float)), 0, 0, 0
            };
            AscendC::DataCopyPadExtParams<float> padParams{true, 0, 0, 0.0f};
            AscendC::DataCopyPad(twLocal, twiddleGm_[0], copyParams, padParams);
        }
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        // --- Zero-initialize data buffer ---
        {
            AscendC::LocalTensor<float> dataLocal = dataBuf_.Get<float>();
            AscendC::Duplicate(dataLocal, 0.0f, 2U * static_cast<uint32_t>(N));
        }
        AscendC::PipeBarrier<PIPE_V>();

        // --- Load input row ---
        AscendC::LocalTensor<T> inLocal = inBuf_.Get<T>();
        {
            AscendC::DataCopyExtParams copyParams{
                1, static_cast<uint16_t>(static_cast<uint32_t>(L) * sizeof(T)), 0, 0, 0
            };
            AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
            AscendC::DataCopyPad(inLocal,
                                  xGm_[static_cast<uint64_t>(bi) * C * L +
                                       static_cast<uint64_t>(ci) * L],
                                  copyParams, padParams);
        }
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        // --- Interleave input as real parts in data buffer ---
        // data[2*j] = float(input[j]), data[2*j+1] = 0
        {
            AscendC::LocalTensor<float> dataLocal = dataBuf_.Get<float>();

            // For float32 input: direct copy
            if constexpr (std::is_same_v<T, float>) {
                for (int32_t j = 0; j < L; ++j) {
                    dataLocal.SetValue(2U * j, inLocal.GetValue(j));
                }
            } else {
                // Cast fp16/bf16 to fp32 first
                AscendC::LocalTensor<float> castLocal = castBuf_.Get<float>();
                AscendC::Cast(castLocal, inLocal, AscendC::RoundMode::CAST_NONE,
                               static_cast<uint32_t>(L));
                AscendC::PipeBarrier<PIPE_V>();
                for (int32_t j = 0; j < L; ++j) {
                    dataLocal.SetValue(2U * j, castLocal.GetValue(j));
                }
            }
        }
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void Compute()
    {
        AscendC::LocalTensor<float> dataLocal = dataBuf_.Get<float>();
        AscendC::LocalTensor<float> twLocal = twiddleBuf_.Get<float>();

        // --- Step 1: Bit-reversal permutation ---
        // Swap interleaved complex pairs: for k < rev(k), swap
        for (int32_t i = 0; i < N; ++i) {
            int32_t rev = BitReverse(i, numStages_);
            if (i < rev) {
                float tmpRe = dataLocal.GetValue(2U * i);
                float tmpIm = dataLocal.GetValue(2U * i + 1);
                dataLocal.SetValue(2U * i, dataLocal.GetValue(2U * rev));
                dataLocal.SetValue(2U * i + 1, dataLocal.GetValue(2U * rev + 1));
                dataLocal.SetValue(2U * rev, tmpRe);
                dataLocal.SetValue(2U * rev + 1, tmpIm);
            }
        }
        AscendC::PipeBarrier<PIPE_V>();

        // --- Step 2: FFT stages (Cooley-Tukey DIT) ---
        for (int32_t stage = 1; stage <= numStages_; ++stage) {
            int32_t stepLen = 1 << (stage - 1);   // half-group size
            int32_t groupSize = stepLen << 1;      // full group size
            int32_t numGroups = N / groupSize;

            for (int32_t group = 0; group < numGroups; ++group) {
                int32_t base = group * groupSize;

                for (int32_t k = 0; k < stepLen; ++k) {
                    int32_t bot = base + k;
                    int32_t top = base + k + stepLen;
                    int32_t twIdx = k * (N / groupSize);

                    // Load values
                    float xBotRe = dataLocal.GetValue(2U * bot);
                    float xBotIm = dataLocal.GetValue(2U * bot + 1);
                    float xTopRe = dataLocal.GetValue(2U * top);
                    float xTopIm = dataLocal.GetValue(2U * top + 1);

                    // Twiddle: W = cos(2π*twIdx/N) - j*sin(2π*twIdx/N)
                    float wRe = twLocal.GetValue(2U * twIdx);
                    float wIm = twLocal.GetValue(2U * twIdx + 1);

                    // Complex multiply: t = W * X[top]
                    float tRe = wRe * xTopRe - wIm * xTopIm;
                    float tIm = wRe * xTopIm + wIm * xTopRe;

                    // Butterfly
                    dataLocal.SetValue(2U * bot, xBotRe + tRe);
                    dataLocal.SetValue(2U * bot + 1, xBotIm + tIm);
                    dataLocal.SetValue(2U * top, xBotRe - tRe);
                    dataLocal.SetValue(2U * top + 1, xBotIm - tIm);
                }
            }
        }
        AscendC::PipeBarrier<PIPE_V>();

        // --- Step 3: Normalize by N ---
        float invN = 1.0f / static_cast<float>(N);
        {
            AscendC::LocalTensor<float> outReal = outRealBuf_.Get<float>();
            AscendC::LocalTensor<float> outImag = outImagBuf_.Get<float>();

            // Extract first outSize complex values and normalize
            for (int32_t j = 0; j < outSize; ++j) {
                outReal.SetValue(j, dataLocal.GetValue(2U * j) * invN);
                outImag.SetValue(j, dataLocal.GetValue(2U * j + 1) * invN);
            }
        }
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void CopyOut(int32_t bi, int32_t ci)
    {
        AscendC::LocalTensor<float> outRealLocal = outRealBuf_.Get<float>();
        AscendC::LocalTensor<float> outImagLocal = outImagBuf_.Get<float>();

        // Write real part
        {
            AscendC::DataCopyExtParams copyParams{
                1, static_cast<uint16_t>(static_cast<uint32_t>(outSize) * sizeof(float)), 0, 0, 0
            };
            AscendC::DataCopyPad(
                yRealGm_[static_cast<uint64_t>(bi) * C * outSize +
                         static_cast<uint64_t>(ci) * outSize],
                outRealLocal, copyParams);
        }

        // Write imag part
        {
            AscendC::DataCopyExtParams copyParams{
                1, static_cast<uint16_t>(static_cast<uint32_t>(outSize) * sizeof(float)), 0, 0, 0
            };
            AscendC::DataCopyPad(
                yImagGm_[static_cast<uint64_t>(bi) * C * outSize +
                         static_cast<uint64_t>(ci) * outSize],
                outImagLocal, copyParams);
        }

        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
    }

private:
    int32_t B = 0;
    int32_t C = 0;
    int32_t L = 0;
    int32_t N = 0;
    int32_t outSize = 0;
    int32_t totalTasks = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int32_t numStages_ = 0;
    int64_t dtypeFlag_ = 0;

    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<T> xGm_;
    AscendC::GlobalTensor<float> yRealGm_;
    AscendC::GlobalTensor<float> yImagGm_;
    AscendC::GlobalTensor<float> twiddleGm_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> dataBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> twiddleBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> inBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outRealBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outImagBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;
};

// =========================================================================
// Kernel entry point with dtype dispatch
// =========================================================================

extern "C" __global__ __aicore__ void hyena_fft(
    GM_ADDR x,
    GM_ADDR y_real,
