// Hyena FFT op_host — twiddle factor precomputation + tiling + kernel launch

#include <algorithm>
#include <cmath>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_hyena_fft.h"

namespace ascend_kernel {

std::vector<at::Tensor> hyena_fft(const at::Tensor &x)
{
    // --- Input validation ---
    TORCH_CHECK(x.dim() == 3, "x must be [B, C, L]");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
            x.scalar_type() == at::kBFloat16,
        "x must be float32, float16, or bfloat16");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int32_t B = static_cast<int32_t>(x.sizes()[0]);
    int32_t C = static_cast<int32_t>(x.sizes()[1]);
    int32_t L = static_cast<int32_t>(x.sizes()[2]);
    int32_t N = 2 * L;
    int32_t outSize = L + 1;

    // Check that N is a power of 2
    TORCH_CHECK((N & (N - 1)) == 0, "2*L must be a power of 2");

    // --- dtype flag ---
    int64_t dtypeFlag = 0;
    if (x.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // --- Platform info ---
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManger::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());

    // --- Tiling: distribute B*C tasks across cores ---
    int32_t totalTasks = B * C;
    int32_t usedCoreNum = static_cast<int32_t>(std::min(coreNum, static_cast<int64_t>(totalTasks)));
    if (usedCoreNum < 1) { usedCoreNum = 1; }
    int32_t tasksPerCore = (totalTasks + usedCoreNum - 1) / usedCoreNum;

    // --- Precompute twiddle factors ---
    // W[k] = cos(2πk/N) - j*sin(2πk/N) for k = 0..N/2-1
    // Store interleaved: twiddle[2k]=cos, twiddle[2k+1]=-sin
    int64_t twiddleHalf = static_cast<int64_t>(N) / 2;
    at::Tensor twiddle = at::empty({N}, at::kFloat);
    float *twData = twiddle.data_ptr<float>();
    for (int64_t k = 0; k < twiddleHalf; ++k) {
        double angle = -2.0 * M_PI * static_cast<double>(k) / static_cast<double>(N);
        twData[2 * k] = static_cast<float>(std::cos(angle));
        twData[2 * k + 1] = static_cast<float>(std::sin(angle));
    }

    // --- Output tensors ---
    auto options = at::TensorOptions().dtype(at::kFloat).device(x.device());
    at::Tensor yReal = at::empty({B, C, outSize}, options);
    at::Tensor yImag = at::empty({B, C, outSize}, options);

    // --- Launch kernel (all params must be left values) ---
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(hyena_fft, blockDim,
                    x, yReal, yImag, twiddle,
                    B, C, L, usedCoreNum, tasksPerCore,
                    dtypeFlag);

    return {yReal, yImag};
}

}  // namespace ascend_kernel
