// Hyena FFT kernel: zero-pad + rFFT + normalize
// Cooley-Tukey radix-2 DIT FFT with precomputed twiddle factors

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// =========================================================================
// Inline helpers
// =========================================================================

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    const AscendC::GlobalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, static_cast<uint16_t>(count * static_cast<uint32_t>(sizeof(T))), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> &dst,
    const AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, static_cast<uint16_t>(count * static_cast<uint32_t>(sizeof(T))), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// FFT Kernel — simplified: handles all computation inline
// =========================================================================

template <typename T>
__aicore__ inline void RunHyenaFft(
    AscendC::GlobalTensor<T> &xGm,
    AscendC::GlobalTensor<float> &yRealGm,
    AscendC::GlobalTensor<float> &yImagGm,
    AscendC::LocalTensor<float> &twiddleLocal,
    int32_t B, int32_t C, int32_t L, int32_t N, int32_t outSize,
    AscendC::TPipe *pipePtr)
{
    auto &pipe = *pipePtr;

    // Allocate data buffer for complex interleaved data
    AscendC::LocalTensor<float> dataLocal = pipe.AllocBuffer<float>(2U * static_cast<uint32_t>(N));

    // Allocate temp buffers for I/O
    AscendC::LocalTensor<T> inLocal = pipe.AllocBuffer<T>(static_cast<uint32_t>(L));
    AscendC::LocalTensor<float> outRealLocal = pipe.AllocBuffer<float>(static_cast<uint32_t>(outSize));
    AscendC::LocalTensor<float> outImagLocal = pipe.AllocBuffer<float>(static_cast<uint32_t>(outSize));

    // Cast buffer for fp16/bf16
    AscendC::LocalTensor<float> castBuf;
    if constexpr (!std::is_same_v<T, float>) {
        castBuf = pipe.AllocBuffer<float>(static_cast<uint32_t>(L));
    }

    int32_t totalTasks = B * C;
    int32_t usedCoreNum = pipe.GetBlockDim();
    int32_t tasksPerCore = (totalTasks + usedCoreNum - 1) / usedCoreNum;

    int32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();

    for (int32_t localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
        int32_t taskId = coreIdx * tasksPerCore + localIdx;
        if (taskId >= totalTasks) { continue; }

        int32_t bi = taskId / C;
        int32_t ci = taskId % C;

        // --- Load input row ---
        AscendC::Duplicate(dataLocal, 0.0f, 2U * static_cast<uint32_t>(N));
        AscendC::PipeBarrier<PIPE_V>();

        LoadGmToUb<T>(inLocal, xGm, static_cast<uint32_t>(L));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        // --- Interleave input as real parts ---
        if constexpr (std::is_same_v<T, float>) {
            for (int32_t j = 0; j < L; ++j) {
                dataLocal.SetValue(2U * j, inLocal.GetValue(j));
            }
        } else {
            AscendC::Cast(castBuf, inLocal, AscendC::RoundMode::CAST_NONE, static_cast<uint32_t>(L));
            AscendC::PipeBarrier<PIPE_V>();
            for (int32_t j = 0; j < L; ++j) {
                dataLocal.SetValue(2U * j, castBuf.GetValue(j));
            }
        }
        AscendC::PipeBarrier<PIPE_V>();

        // --- Compute log2(N) ---
        int32_t numStages = 0;
        int32_t temp = N;
        while (temp > 1) { temp >>= 1; numStages++; }

        // --- Bit-reversal ---
        {
            auto bitReverse = [numStages](int32_t idx) -> int32_t {
                int32_t result = 0;
                for (int32_t b = 0; b < numStages; ++b) {
                    result = (result << 1) | (idx & 1);
                    idx >>= 1;
                }
                return result;
            };
            for (int32_t i = 0; i < N; ++i) {
                int32_t rev = bitReverse(i);
                if (i < rev) {
                    float tmpRe = dataLocal.GetValue(2U * i);
                    float tmpIm = dataLocal.GetValue(2U * i + 1);
                    dataLocal.SetValue(2U * i, dataLocal.GetValue(2U * rev));
                    dataLocal.SetValue(2U * i + 1, dataLocal.GetValue(2U * rev + 1));
                    dataLocal.SetValue(2U * rev, tmpRe);
                    dataLocal.SetValue(2U * rev + 1, tmpIm);
                }
            }
        }
        AscendC::PipeBarrier<PIPE_V>();

        // --- FFT stages ---
        for (int32_t stage = 1; stage <= numStages; ++stage) {
            int32_t stepLen = 1 << (stage - 1);
            int32_t groupSize = stepLen << 1;
            int32_t numGroups = N / groupSize;

            for (int32_t group = 0; group < numGroups; ++group) {
                int32_t base = group * groupSize;

                for (int32_t k = 0; k < stepLen; ++k) {
                    int32_t bot = base + k;
                    int32_t top = base + k + stepLen;
                    int32_t twIdx = k * (N / groupSize);

                    float xBotRe = dataLocal.GetValue(2U * bot);
                    float xBotIm = dataLocal.GetValue(2U * bot + 1);
                    float xTopRe = dataLocal.GetValue(2U * top);
                    float xTopIm = dataLocal.GetValue(2U * top + 1);

                    float wRe = twiddleLocal.GetValue(2U * twIdx);
                    float wIm = twiddleLocal.GetValue(2U * twIdx + 1);

                    float tRe = wRe * xTopRe - wIm * xTopIm;
                    float tIm = wRe * xTopIm + wIm * xTopRe;

                    dataLocal.SetValue(2U * bot, xBotRe + tRe);
                    dataLocal.SetValue(2U * bot + 1, xBotIm + tIm);
                    dataLocal.SetValue(2U * top, xBotRe - tRe);
                    dataLocal.SetValue(2U * top + 1, xBotIm - tIm);
                }
            }
        }
        AscendC::PipeBarrier<PIPE_V>();

        // --- Normalize and extract output ---
        float invN = 1.0f / static_cast<float>(N);
        for (int32_t j = 0; j < outSize; ++j) {
            outRealLocal.SetValue(j, dataLocal.GetValue(2U * j) * invN);
            outImagLocal.SetValue(j, dataLocal.GetValue(2U * j + 1) * invN);
        }
        AscendC::PipeBarrier<PIPE_V>();

        // --- Write outputs ---
        StoreUbToGm<float>(yRealGm, outRealLocal, static_cast<uint32_t>(outSize));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
        StoreUbToGm<float>(yImagGm, outImagLocal, static_cast<uint32_t>(outSize));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
    }

    // Free allocated buffers (done automatically when scope ends but explicit is better)
    if constexpr (!std::is_same_v<T, float>) {
        pipe.FreeBuffer(castBuf);
    }
    pipe.FreeBuffer(outImagLocal);
    pipe.FreeBuffer(outRealLocal);
    pipe.FreeBuffer(inLocal);
    pipe.FreeBuffer(dataLocal);
}

// =========================================================================
// Typedef wrappers (called from dispatch)
// =========================================================================

template <typename T>
__aicore__ inline void HyenaFftDispatch(
    GM_ADDR x, GM_ADDR y_real, GM_ADDR y_imag, GM_ADDR twiddle,
    int32_t B, int32_t C, int32_t L, int32_t N, int32_t outSize,
    int32_t usedCoreNum, int32_t tasksPerCore, AscendC::TPipe *pipePtr)
{
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<float> yRealGm;
    AscendC::GlobalTensor<float> yImagGm;

    xGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), static_cast<uint64_t>(B) * C * L);
